// THE WORLD — Monday 23 November 2026
// A program that draws one newspaper front page summing up the day's world
// news. Node 22, standard library only, no network. It renders the whole
// page into a 3x supersampled buffer, downsamples to 1024x1024, and writes
// a deterministic PNG. Run with:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
import * as fs from "node:fs";
import * as zlib from "node:zlib";

// ---------------------------------------------------------------------------
// Page and supersampling
// ---------------------------------------------------------------------------
const W = 1024;
const H = 1024;
const SS = 3; // supersample factor
const SW = W * SS;
const SH = H * SS;

const buf = new Uint8Array(SW * SH * 3); // supersampled RGB canvas

type RGB = [number, number, number];
const PAPER: RGB = [247, 241, 222];
const INK: RGB = [28, 24, 20];
const RED: RGB = [176, 32, 26];
const GREY: RGB = [96, 90, 80];
const LIGHT_GREY: RGB = [120, 114, 102];
const BLUE: RGB = [38, 84, 138];
const TEAL: RGB = [24, 120, 108];
const ORANGE: RGB = [198, 110, 24];
const PURPLE: RGB = [110, 76, 140];
const GREEN: RGB = [46, 130, 62];
const NIGHT: RGB = [18, 26, 48];
const SEA: RGB = [28, 52, 88];
const GOLD: RGB = [222, 158, 44];
const CREAM: RGB = [250, 246, 232];
const MAP_BLUE: RGB = [178, 208, 224];
const MAP_DOT: RGB = [52, 96, 120];

// Region colours, in legend order.
const REGIONS: Array<[string, RGB]> = [
  ["MIDDLE EAST", [160, 52, 36]],
  ["EUROPE", BLUE],
  ["ASIA-PACIFIC", TEAL],
  ["AMERICAS", ORANGE],
  ["AFRICA", PURPLE],
  ["WORLD", [74, 74, 74]],
  ["SPORT & CULTURE", GREEN],
];

function regionColor(name: string): RGB {
  for (const [n, c] of REGIONS) if (n === name) return c;
  return [74, 74, 74];
}

// ---------------------------------------------------------------------------
// Low-level drawing on the supersampled buffer
// ---------------------------------------------------------------------------
function fillAll(c: RGB): void {
  for (let i = 0; i < SW * SH; i++) {
    buf[i * 3] = c[0];
    buf[i * 3 + 1] = c[1];
    buf[i * 3 + 2] = c[2];
  }
}

function setPx(sx: number, sy: number, c: RGB): void {
  if (sx < 0 || sy < 0 || sx >= SW || sy >= SH) return;
  const i = (sy * SW + sx) * 3;
  buf[i] = c[0];
  buf[i + 1] = c[1];
  buf[i + 2] = c[2];
}

// Filled rectangle, page coordinates (floats allowed, edges rounded).
function rect(x: number, y: number, w: number, h: number, c: RGB): void {
  const x0 = Math.max(0, Math.round(x * SS));
  const y0 = Math.max(0, Math.round(y * SS));
  const x1 = Math.min(SW, Math.round((x + w) * SS));
  const y1 = Math.min(SH, Math.round((y + h) * SS));
  for (let yy = y0; yy < y1; yy++) {
    let base = (yy * SW + x0) * 3;
    for (let xx = x0; xx < x1; xx++) {
      buf[base] = c[0];
      buf[base + 1] = c[1];
      buf[base + 2] = c[2];
      base += 3;
    }
  }
}

// Horizontal rule of given thickness.
function rule(x: number, y: number, w: number, t: number, c: RGB): void {
  rect(x, y, w, t, c);
}

// Filled polygons (one or more contours), points in supersampled
// coordinates. Even-odd scanline fill over ALL contours at once, which is
// what glyph counters (the holes in O, D, B, ...) need: a point inside a
// counter crosses two boundaries and stays empty. Filling each contour
// separately would paint the holes solid.
function fillPolysSS(polys: Array<Array<[number, number]>>, c: RGB): void {
  let minY = Infinity;
  let maxY = -Infinity;
  let total = 0;
  for (const pts of polys) {
    total += pts.length;
    for (const [, y] of pts) {
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  if (total < 3) return;
  const y0 = Math.max(0, Math.floor(minY));
  const y1 = Math.min(SH - 1, Math.ceil(maxY));
  const xs: number[] = [];
  for (let y = y0; y <= y1; y++) {
    const yc = y + 0.5;
    xs.length = 0;
    for (const pts of polys) {
      for (let i = 0; i < pts.length; i++) {
        const [x0, y0p] = pts[i];
        const [x1, y1p] = pts[(i + 1) % pts.length];
        if ((y0p <= yc && y1p > yc) || (y1p <= yc && y0p > yc)) {
          xs.push(x0 + ((yc - y0p) / (y1p - y0p)) * (x1 - x0));
        }
      }
    }
    if (xs.length < 2) continue;
    xs.sort((a, b) => a - b);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const xa = Math.max(0, Math.ceil(xs[k]));
      const xb = Math.min(SW - 1, Math.floor(xs[k + 1]));
      let base = (y * SW + xa) * 3;
      for (let xx = xa; xx <= xb; xx++) {
        buf[base] = c[0];
        buf[base + 1] = c[1];
        buf[base + 2] = c[2];
        base += 3;
      }
    }
  }
}

// Filled polygon, points in supersampled coordinates.
function fillPolySS(pts: Array<[number, number]>, c: RGB): void {
  fillPolysSS([pts], c);
}

// Filled polygon, points in page coordinates.
function fillPoly(pts: Array<[number, number]>, c: RGB): void {
  fillPolySS(
    pts.map(([x, y]): [number, number] => [x * SS, y * SS]),
    c,
  );
}

// Circle/ellipse outline points, page coordinates.
function ellipsePts(
  cx: number,
  cy: number,
  rx: number,
  ry: number,
): Array<[number, number]> {
  const pts: Array<[number, number]> = [];
  const n = 44;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]);
  }
  return pts;
}

// Ellipse as a polygon, page coordinates.
function ellipse(cx: number, cy: number, rx: number, ry: number, c: RGB): void {
  fillPoly(ellipsePts(cx, cy, rx, ry), c);
}

function circle(cx: number, cy: number, r: number, c: RGB): void {
  ellipse(cx, cy, r, r, c);
}

// Thick line segment, drawn by stamping discs along it. Page coordinates.
function thickLine(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  thick: number,
  c: RGB,
): void {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const len = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(len * SS * 0.7));
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    circle(x0 + dx * t, y0 + dy * t, thick / 2, c);
  }
}

// Ring (outline circle): the band between two circles, filled even-odd so
// whatever lies underneath shows through the middle. Page coordinates.
function ring(cx: number, cy: number, r: number, t: number, c: RGB): void {
  fillPolysSS(
    [
      ellipsePts(cx, cy, r, r).map(
        ([x, y]): [number, number] => [x * SS, y * SS],
      ),
      ellipsePts(cx, cy, Math.max(0.5, r - t), Math.max(0.5, r - t)).map(
        ([x, y]): [number, number] => [x * SS, y * SS],
      ),
    ],
    c,
  );
}

// ---------------------------------------------------------------------------
// PNG encoding (deterministic: fixed deflate level, no timestamps anywhere)
// ---------------------------------------------------------------------------
const CRC_TABLE: Uint32Array = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let v = n;
    for (let k = 0; k < 8; k++) v = v & 1 ? 0xedb88320 ^ (v >>> 1) : v >>> 1;
    t[n] = v >>> 0;
  }
  return t;
})();

function crc32(data: Buffer): number {
  let crc = 0xffffffff;
  for (let i = 0; i < data.length; i++) {
    crc = CRC_TABLE[(crc ^ data[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function pngChunk(type: string, data: Buffer): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, "ascii");
  data.copy(out, 8);
  const crcData = Buffer.concat([Buffer.from(type, "ascii"), data]);
  out.writeUInt32BE(crc32(crcData), 8 + data.length);
  return out;
}

function encodePng(rgb: Uint8Array, w: number, h: number): Buffer {
  const raw = Buffer.alloc(h * (1 + w * 3));
  for (let y = 0; y < h; y++) {
    raw[y * (1 + w * 3)] = 0; // filter: none
    Buffer.from(rgb.buffer, rgb.byteOffset + y * w * 3, w * 3).copy(
      raw,
      y * (1 + w * 3) + 1,
    );
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type RGB
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;
  const idat = zlib.deflateSync(raw, { level: 9 });
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  return Buffer.concat([
    sig,
    pngChunk("IHDR", ihdr),
    pngChunk("IDAT", idat),
    pngChunk("IEND", Buffer.alloc(0)),
  ]);
}

// Downsample the supersampled buffer to the final 1024x1024 RGB image.
function downsample(): Uint8Array {
  const out = new Uint8Array(W * H * 3);
  const n = SS * SS;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let r = 0;
      let g = 0;
      let b = 0;
      for (let dy = 0; dy < SS; dy++) {
        let base = ((y * SS + dy) * SW + x * SS) * 3;
        for (let dx = 0; dx < SS; dx++) {
          r += buf[base];
          g += buf[base + 1];
          b += buf[base + 2];
          base += 3;
        }
      }
      const j = (y * W + x) * 3;
      out[j] = Math.round(r / n);
      out[j + 1] = Math.round(g / n);
      out[j + 2] = Math.round(b / n);
    }
  }
  return out;
}

