// ---------------------------------------------------------------------------
// Text engine
// ---------------------------------------------------------------------------
let fitOk = true;
const fitProblems: string[] = [];

function markBad(msg: string): void {
  fitOk = false;
  fitProblems.push(msg);
  console.error("FIT PROBLEM: " + msg);
}

function glyphOf(face: Face, ch: string): [number, number[][][]] | null {
  const g = face.glyphs[ch];
  if (g) return g;
  const q = face.glyphs["?"];
  return q || null;
}

// Width of a string at a given size, in page pixels.
function textWidth(s: string, face: Face, size: number): number {
  let w = 0;
  for (const ch of s) {
    const g = glyphOf(face, ch);
    if (g) w += (g[0] * size) / face.upem;
  }
  return w;
}

// Draw one glyph. penX is the left edge in page pixels, baseY the baseline.
function drawGlyph(
  face: Face,
  ch: string,
  penX: number,
  baseY: number,
  size: number,
  c: RGB,
): number {
  const g = glyphOf(face, ch);
  if (!g) return 0;
  const [adv, contours] = g;
  const k = (size / face.upem) * SS;
  // All contours of the glyph go through ONE fill, so counters stay hollow.
  const polys: Array<Array<[number, number]>> = [];
  for (const contour of contours) {
    if (contour.length < 3) continue;
    const pts: Array<[number, number]> = [];
    for (const [x, y] of contour) {
      pts.push([penX * SS + x * k, baseY * SS + y * k]);
    }
    polys.push(pts);
  }
  if (polys.length > 0) fillPolysSS(polys, c);
  return (adv * size) / face.upem;
}

// Draw a single line of text at a baseline. Returns the width drawn.
function drawText(
  x: number,
  baseY: number,
  s: string,
  face: Face,
  size: number,
  c: RGB,
): number {
  let penX = x;
  for (const ch of s) penX += drawGlyph(face, ch, penX, baseY, size, c);
  return penX - x;
}

// Draw a centred line. y is the baseline.
function drawTextCentred(
  cx: number,
  baseY: number,
  s: string,
  face: Face,
  size: number,
  c: RGB,
): number {
  const w = textWidth(s, face, size);
  return drawText(cx - w / 2, baseY, s, face, size, c);
}

// Greedy word wrap. Returns the lines.
function wrapText(s: string, face: Face, size: number, maxW: number): string[] {
  const words = s.split(" ");
  const lines: string[] = [];
  let cur = "";
  for (const word of words) {
    const trial = cur === "" ? word : cur + " " + word;
    if (textWidth(trial, face, size) <= maxW || cur === "") {
      cur = trial;
    } else {
      lines.push(cur);
      cur = word;
    }
  }
  if (cur !== "") lines.push(cur);
  return lines;
}

// Draw a wrapped paragraph. y is the TOP of the first line's cap area.
// Shrinks the size (down to minSize) until it fits in maxLines.
// Returns the height used. Marks the fit bad if it still does not fit.
function drawPara(
  x: number,
  y: number,
  s: string,
  face: Face,
  size: number,
  maxW: number,
  maxLines: number,
  lineH: number,
  c: RGB,
  minSize: number,
  label: string,
): number {
  let sz = size;
  let lines = wrapText(s, face, sz, maxW);
  while (lines.length > maxLines && sz > minSize) {
    sz = Math.max(minSize, sz - 0.5);
    lines = wrapText(s, face, sz, maxW);
  }
  if (lines.length > maxLines) {
    markBad(
      `${label}: needs ${lines.length} lines at min size ${minSize}, max ${maxLines}`,
    );
  }
  for (let i = 0; i < lines.length; i++) {
    drawText(x, y + i * lineH + sz * 0.8, lines[i], face, sz, c);
  }
  return lines.length * lineH;
}

// Draw a single line, shrinking until it fits maxW. Returns the size used.
function drawSingleLine(
  x: number,
  baseY: number,
  s: string,
  face: Face,
  size: number,
  maxW: number,
  minSize: number,
  c: RGB,
  label: string,
): number {
  let sz = size;
  while (textWidth(s, face, sz) > maxW && sz > minSize) sz -= 0.5;
  if (textWidth(s, face, sz) > maxW) {
    markBad(`${label}: does not fit at min size ${minSize}`);
  }
  drawText(x, baseY, s, face, sz, c);
  return sz;
}

