// ---------------------------------------------------------------------------
// Illustrated scenes for the three top stories. Each draws inside a box
// (x, y, w, h) in page coordinates, in a flat vector style.
// ---------------------------------------------------------------------------
function starField(x: number, y: number, w: number, h: number): void {
  // Fixed star positions (fractions of the box), so the render is stable.
  const stars: Array<[number, number, number]> = [
    [0.08, 0.2, 1.4], [0.2, 0.08, 1.1], [0.34, 0.3, 1.6], [0.48, 0.12, 1.0],
    [0.62, 0.26, 1.4], [0.74, 0.1, 1.2], [0.86, 0.3, 1.5], [0.94, 0.16, 1.0],
    [0.14, 0.44, 1.0], [0.56, 0.4, 1.2], [0.8, 0.46, 1.0], [0.28, 0.52, 1.1],
  ];
  for (const [fx, fy, r] of stars) {
    circle(x + fx * w, y + fy * h, r, CREAM);
  }
}

function droneSilhouette(cx: number, cy: number, s: number, c: RGB): void {
  // A small quad-rotor drone seen from below: body plus four arms.
  circle(cx, cy, s * 0.32, c);
  thickLine(cx - s * 0.6, cy - s * 0.3, cx + s * 0.6, cy + s * 0.3, s * 0.16, c);
  thickLine(cx - s * 0.6, cy + s * 0.3, cx + s * 0.6, cy - s * 0.3, s * 0.16, c);
  circle(cx - s * 0.6, cy - s * 0.3, s * 0.14, c);
  circle(cx + s * 0.6, cy + s * 0.3, s * 0.14, c);
  circle(cx - s * 0.6, cy + s * 0.3, s * 0.14, c);
  circle(cx + s * 0.6, cy - s * 0.3, s * 0.14, c);
}

function burst(cx: number, cy: number, r: number, c: RGB): void {
  // An air-defence burst: a spiky star.
  const pts: Array<[number, number]> = [];
  const n = 12;
  for (let i = 0; i < n * 2; i++) {
    const a = (i / (n * 2)) * Math.PI * 2;
    const rr = i % 2 === 0 ? r : r * 0.38;
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr]);
  }
  fillPoly(pts, c);
  circle(cx, cy, r * 0.3, [255, 236, 170]);
}

function sceneSea(x: number, y: number, w: number, h: number): void {
  rect(x, y, w, h, NIGHT);
  starField(x, y, w, h * 0.55);
  circle(x + w * 0.82, y + h * 0.16, 9, GOLD); // low moon
  circle(x + w * 0.82, y + h * 0.16, 12, [222, 158, 44]);
  // Sea.
  rect(x, y + h * 0.55, w, h * 0.45, SEA);
  for (let i = 0; i < 5; i++) {
    const wy = y + h * (0.62 + i * 0.07);
    rule(x + w * (0.06 + i * 0.03), wy, w * (0.5 - i * 0.05), 1.2, [90, 130, 180]);
  }
  // The corvette, listing to starboard, bow down, burning.
  const hx = x + w * 0.3;
  const hy = y + h * 0.62;
  fillPoly(
    [
      [hx - 78, hy - 8],
      [hx + 62, hy - 8],
      [hx + 78, hy + 6],
      [hx - 66, hy + 6],
    ],
    [12, 16, 30],
  );
  rect(hx - 34, hy - 26, 44, 18, [12, 16, 30]); // superstructure
  rect(hx + 8, hy - 40, 4, 16, [12, 16, 30]); // mast
  circle(hx + 30, hy - 14, 7, GOLD); // fire glow
  circle(hx + 42, hy - 18, 4.5, [238, 96, 32]);
  fillPoly(
    [
      [hx + 24, hy - 12],
      [hx + 34, hy - 34],
      [hx + 44, hy - 12],
    ],
    [238, 96, 32],
  );
  // Smoke.
  circle(hx + 30, hy - 40, 6, [140, 140, 140]);
  circle(hx + 38, hy - 48, 8, [160, 160, 160]);
  circle(hx + 48, hy - 56, 6, [140, 140, 140]);
  // Naval drones closing in.
  droneSilhouette(x + w * 0.82, y + h * 0.72, 11, [200, 210, 225]);
  droneSilhouette(x + w * 0.9, y + h * 0.58, 8, [200, 210, 225]);
  droneSilhouette(x + w * 0.68, y + h * 0.82, 7, [200, 210, 225]);
  circle(x + w * 0.82, y + h * 0.72, 2, RED);
}

function sceneSky(x: number, y: number, w: number, h: number): void {
  rect(x, y, w, h, NIGHT);
  starField(x, y, w, h * 0.6);
  circle(x + w * 0.88, y + h * 0.2, 8, [226, 222, 204]); // moon
  // City skyline.
  const base = y + h;
  const blocks: Array<[number, number, number]> = [
    [0.02, 0.24, 0.3], [0.2, 0.34, 0.42], [0.38, 0.28, 0.36],
    [0.56, 0.4, 0.5], [0.74, 0.3, 0.4], [0.88, 0.36, 0.46],
  ];
  for (const [fx, fw, fh] of blocks) {
    rect(x + fx * w, base - fh * h, fw * w, fh * h, [10, 14, 26]);
  }
  // Lit windows.
  for (let i = 0; i < 14; i++) {
    const wx = x + w * (0.05 + ((i * 0.067) % 0.9));
    const wy = base - h * (0.1 + ((i * 0.11) % 0.34));
    rect(wx, wy, 3, 3.5, GOLD);
  }
  // Drones and bursts over the city.
  droneSilhouette(x + w * 0.22, y + h * 0.24, 10, [200, 210, 225]);
  droneSilhouette(x + w * 0.62, y + h * 0.16, 8, [200, 210, 225]);
  burst(x + w * 0.42, y + h * 0.3, 13, GOLD);
  burst(x + w * 0.78, y + h * 0.36, 10, GOLD);
  burst(x + w * 0.1, y + h * 0.42, 8, GOLD);
}

function sceneGlobe(x: number, y: number, w: number, h: number): void {
  rect(x, y, w, h, [214, 230, 222]); // pale sky
  rect(x, y + h * 0.62, w, h * 0.38, [126, 178, 118]); // ground
  // Globe.
  const gx = x + w * 0.24;
  const gy = y + h * 0.34;
  circle(gx, gy, 30, [64, 140, 196]);
  ellipse(gx - 8, gy - 6, 12, 8, [58, 150, 84]);
  ellipse(gx + 10, gy + 10, 10, 7, [58, 150, 84]);
  ellipse(gx + 2, gy - 16, 7, 5, [58, 150, 84]);
  ring(gx, gy, 30, 2, [38, 84, 138]);
  // Flag row: small summit flags.
  for (let i = 0; i < 4; i++) {
    const fx = x + w * (0.52 + i * 0.09);
    rule(fx, y + h * 0.3, 1.5, h * 0.32, INK);
    rect(
      fx + 1.5,
      y + h * 0.3,
      16,
      9,
      i === 0 ? RED : i === 1 ? BLUE : i === 2 ? TEAL : ORANGE,
    );
  }
  // Crossed-out oil drop.
  const dx = x + w * 0.82;
  const dy = y + h * 0.42;
  fillPoly(
    [
      [dx, dy - 22],
      [dx + 13, dy + 4],
      [dx + 13, dy + 12],
      [dx - 13, dy + 12],
      [dx - 13, dy + 4],
    ],
    [20, 20, 20],
  );
  ellipse(dx, dy + 10, 13, 7, [20, 20, 20]);
  thickLine(dx - 20, dy - 26, dx + 20, dy + 26, 6, RED);
  circle(dx + w * 0.08, y + h * 0.2, 8, GOLD); // sun
}

function drawScene(kind: string, x: number, y: number, w: number, h: number): void {
  if (kind === "sea") sceneSea(x, y, w, h);
  else if (kind === "sky") sceneSky(x, y, w, h);
  else sceneGlobe(x, y, w, h);
  rect(x, y, w, 1.6, INK);
  rect(x, y + h - 1.6, w, 1.6, INK);
  rect(x, y, 1.6, h, INK);
  rect(x + w - 1.6, y, 1.6, h, INK);
}

// ---------------------------------------------------------------------------
// Small icons for the ten mid stories, drawn in a 30x30 box.
// ---------------------------------------------------------------------------
function drawIcon(kind: string, x: number, y: number, c: RGB): void {
  if (kind === "chart") {
    rule(x + 3, y + 25, 24, 1.6, c);
    rule(x + 3, y + 4, 1.6, 22, c);
    thickLine(x + 5, y + 22, x + 12, y + 15, 2, RED);
    thickLine(x + 12, y + 15, x + 19, y + 18, 2, RED);
    thickLine(x + 19, y + 18, x + 26, y + 7, 2, RED);
    fillPoly([[x + 26, y + 7], [x + 21, y + 7], [x + 26, y + 12]], RED);
  } else if (kind === "planes") {
    fillPoly(
      [
        [x + 4, y + 16], [x + 26, y + 16], [x + 28, y + 18],
        [x + 26, y + 20], [x + 4, y + 20],
      ],
      c,
    );
    fillPoly(
      [[x + 12, y + 16], [x + 15, y + 8], [x + 18, y + 16]],
      c,
    );
    fillPoly(
      [[x + 13, y + 20], [x + 15, y + 26], [x + 17, y + 20]],
      c,
    );
    circle(x + 24, y + 12, 2, RED);
  } else if (kind === "tanker") {
    fillPoly(
      [[x + 3, y + 18], [x + 27, y + 18], [x + 24, y + 25], [x + 6, y + 25]],
      c,
    );
    rect(x + 8, y + 10, 10, 8, c);
    fillPoly([[x + 20, y + 10], [x + 23, y + 2], [x + 26, y + 10]], [238, 96, 32]);
    circle(x + 23, y + 6, 3, GOLD);
  } else if (kind === "refinery") {
    rect(x + 4, y + 12, 5, 14, c);
    rect(x + 11, y + 8, 5, 18, c);
    rect(x + 18, y + 14, 5, 12, c);
    fillPoly([[x + 22, y + 14], [x + 25, y + 5], [x + 28, y + 14]], [238, 96, 32]);
    circle(x + 25, y + 9, 2.5, GOLD);
    rule(x + 3, y + 26, 24, 1.6, c);
  } else if (kind === "drones") {
    droneSilhouette(x + 9, y + 9, 7, c);
    droneSilhouette(x + 21, y + 14, 7, c);
    droneSilhouette(x + 12, y + 22, 7, c);
    circle(x + 9, y + 9, 1.6, RED);
    circle(x + 21, y + 14, 1.6, RED);
  } else if (kind === "train") {
    rect(x + 5, y + 8, 20, 12, c);
    rect(x + 8, y + 11, 4, 4, PAPER);
    rect(x + 14, y + 11, 4, 4, PAPER);
    rect(x + 20, y + 11, 3, 4, PAPER);
    circle(x + 9, y + 23, 3, INK);
    circle(x + 21, y + 23, 3, INK);
    rule(x + 3, y + 26, 24, 1.6, c);
  } else if (kind === "rubble") {
    fillPoly([[x + 3, y + 26], [x + 12, y + 12], [x + 18, y + 26]], [120, 116, 108]);
    fillPoly([[x + 13, y + 26], [x + 21, y + 16], [x + 27, y + 26]], [150, 146, 136]);
    circle(x + 20, y + 8, 4, [170, 170, 170]);
    circle(x + 24, y + 5, 3, [190, 190, 190]);
  } else if (kind === "cricket") {
    thickLine(x + 8, y + 24, x + 20, y + 8, 3.4, c);
    ellipse(x + 21, y + 7, 4, 5.4, c);
    circle(x + 24, y + 22, 3, RED);
    rule(x + 4, y + 26, 22, 1.6, c);
  } else if (kind === "capitol") {
    ellipse(x + 15, y + 8, 8, 5, c);
    rect(x + 7, y + 8, 16, 3, c);
    rect(x + 6, y + 11, 18, 2, c);
    for (let i = 0; i < 4; i++) rect(x + 7 + i * 4.4, y + 13, 2, 10, c);
    rect(x + 5, y + 23, 20, 2.4, c);
  } else {
    // negotiating table
    rect(x + 5, y + 14, 20, 3, c);
    rect(x + 7, y + 17, 2.4, 8, c);
    rect(x + 21, y + 17, 2.4, 8, c);
    circle(x + 8, y + 9, 3.4, RED);
    circle(x + 22, y + 9, 3.4, BLUE);
  }
}

// ---------------------------------------------------------------------------
// World map: a dot matrix over my own ellipse landmasses, plus ten numbered
// pins that point at stories in the numbered list below.
// ---------------------------------------------------------------------------
const LAND: Array<[number, number, number, number]> = [
  // lon, lat, rx (lon), ry (lat)
  [-100, 50, 32, 16], // North America
  [-152, 64, 12, 7], // Alaska
  [-42, 74, 9, 6], // Greenland
  [-88, 15, 8, 5], // Central America
  [-60, -14, 13, 19], // South America
  [14, 52, 15, 9], // Europe
  [-1, 54, 3.5, 4.5], // Britain
  [18, 4, 16, 21], // Africa
  [45, 30, 11, 8], // Middle East
  [95, 55, 38, 14], // Northern Asia
  [78, 21, 8, 10], // India
  [103, 13, 9, 8], // SE Asia
  [115, -2, 12, 4], // Indonesia
  [134, -25, 13, 8], // Australia
  [139, 37, 4, 6], // Japan
  [172, -41, 3, 5], // New Zealand
];

function onLand(lon: number, lat: number): boolean {
  for (const [clon, clat, rx, ry] of LAND) {
    const dx = (lon - clon) / rx;
    const dy = (lat - clat) / ry;
    if (dx * dx + dy * dy <= 1) return true;
  }
  return false;
}

// story number in the list below, lon, lat, display offset (px) so close
// pins do not sit on top of each other
const PINS: Array<[number, number, number, number, number]> = [
  [1, -74, 41, -10, -6], // Wall Street, New York
  [9, 121, 24, 0, 0], // Taiwan
  [12, 56, 26, -2, 13], // Hormuz
  [20, 37, 35, 13, -9], // Syria
  [22, 66, 34, 11, -7], // Afghanistan
  [23, 35, 32, -16, 4], // West Bank
  [26, -72, 19, 9, 9], // Haiti
  [28, 32, 1, 0, 0], // Uganda
  [30, 8, 9, -6, 3], // Nigeria
  [37, 30, 37, -16, -8], // COP31, Antalya
];

function drawMap(x: number, y: number, w: number, h: number): void {
  rect(x, y, w, h, MAP_BLUE);
  const step = 6;
  for (let py = y + 3; py < y + h - 2; py += step) {
    for (let px = x + 3; px < x + w - 2; px += step) {
      const lon = ((px - x) / w) * 360 - 180;
      const lat = 90 - ((py - y) / h) * 180;
      if (onLand(lon, lat)) circle(px, py, 1.5, MAP_DOT);
    }
  }
  for (const [num, lon, lat, dx, dy] of PINS) {
    const px = x + ((lon + 180) / 360) * w + dx;
    const py = y + ((90 - lat) / 180) * h + dy;
    circle(px, py, 7.5, RED);
    ring(px, py, 7.5, 1, [255, 255, 255]);
    const label = String(num);
    const tw = textWidth(label, SANS_BOLD, 9);
    drawText(px - tw / 2, py + 3, label, SANS_BOLD, 9, [255, 255, 255]);
  }
  rect(x, y, w, 1.6, INK);
  rect(x, y + h - 1.6, w, 1.6, INK);
  rect(x, y, 1.6, h, INK);
  rect(x + w - 1.6, y, 1.6, h, INK);
}

// ---------------------------------------------------------------------------
// Page layout
// ---------------------------------------------------------------------------
const M = 20; // content margin
const CW = W - 2 * M; // 984

function drawStats(y: number): number {
  const cellW = CW / 6;
  for (let i = 0; i < STATS.length; i++) {
    const [value, label] = STATS[i];
    const cx = M + cellW * i + cellW / 2;
    drawTextCentred(cx, y + 28, value, SERIF_BOLD, 36, RED);
    drawSingleLine(
      M + cellW * i + 4,
      y + 43,
      label,
      SANS,
      10,
      cellW - 8,
      8.5,
      INK,
      `stat ${i + 1}`,
    );
    if (i > 0) rule(M + cellW * i, y + 6, 1, 36, [210, 200, 178]);
  }
  return y + 48;
}

function drawTimelineCell(
  x: number,
  y: number,
  time: string,
  text: string,
  w: number,
): void {
  // First line starts after the red time; the rest uses the full width.
  const timeW = textWidth(time, SANS_BOLD, 11);
  const firstW = w - timeW - 5;
  const firstLines = wrapText(text, SANS, 11, firstW);
  const rest = firstLines.slice(1).join(" ");
  const restLines = rest === "" ? [] : wrapText(rest, SANS, 11, w);
  const lines = [firstLines[0], ...restLines].slice(0, 2);
  if (1 + restLines.length > 2) {
    markBad(`timeline "${time}": text needs more than 2 lines`);
  }
  drawText(x, y + 11, time, SANS_BOLD, 11, RED);
  drawText(x + timeW + 5, y + 11, lines[0] || "", SANS, 11, INK);
  if (lines[1]) drawText(x, y + 24, lines[1], SANS, 11, INK);
}

function drawTimeline(y: number): number {
  drawText(M, y + 15, "THE DAY IN UTC", SERIF_BOLD, 18, INK);
  const colW = CW / 4;
  const rowH = 24;
  for (let i = 0; i < TIMELINE.length; i++) {
    const col = i % 4;
    const row = Math.floor(i / 4);
    drawTimelineCell(
      M + col * colW,
      y + 22 + row * rowH,
      TIMELINE[i][0],
      TIMELINE[i][1],
      colW - 10,
    );
  }
  return y + 22 + 2 * rowH;
}

function drawTopStories(y: number): number {
  const colW = 318;
  const gap = 15;
  let maxH = 0;
  for (let i = 0; i < TOP3.length; i++) {
    const s = TOP3[i];
    const x = M + i * (colW + gap);
    const tagC = regionColor(s.tag);
    drawText(x, y + 11, s.tag, SANS_BOLD, 11, tagC);
    const placeW = textWidth(s.place, SANS_BOLD, 11);
    drawText(x + colW - placeW, y + 11, s.place, SANS_BOLD, 11, GREY);
    const sceneY = y + 16;
    drawScene(s.scene, x, sceneY, colW, 72);
    const headY = sceneY + 72 + 6;
    const headH = drawPara(
      x, headY, s.headline, SERIF_BOLD, 21, colW, 2, 21, INK, 18, `top ${i + 1} headline`,
    );
    const deckY = headY + headH + 2;
    const deckH = drawPara(
      x, deckY, s.deck + " (" + s.source + ")", SANS, 11.5, colW, 2, 14, INK, 10, `top ${i + 1} deck`,
    );
    const colH = 16 + 72 + 6 + headH + 2 + deckH;
    if (colH > maxH) maxH = colH;
  }
  return y + maxH;
}

function drawMidStories(y: number): number {
  drawText(M, y + 15, "ALSO TODAY", SERIF_BOLD, 18, INK);
  rule(M, y + 20, CW, 1.6, INK);
  const colW = (CW - 16) / 2;
  const rowH = 36;
  for (let i = 0; i < MID10.length; i++) {
    const s = MID10[i];
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = M + col * (colW + 16);
    const ry = y + 26 + row * rowH;
    drawIcon(s.icon, x, ry + 2, regionColor(s.tag));
    const tx = x + 38;
    const tw = colW - 38;
    drawSingleLine(tx, ry + 12, s.headline, SERIF_BOLD, 14.5, tw, 12, INK, `mid ${i + 1} headline`);
    drawSingleLine(tx, ry + 25, s.deck + " (" + s.source + ")", SANS, 10.5, tw, 9, GREY, `mid ${i + 1} deck`);
    if (row < 4) rule(x, ry + 31, colW, 0.8, [216, 206, 182]);
  }
  return y + 26 + 5 * rowH;
}

function drawMapAndCheck(y: number): number {
  drawText(M, y + 14, "WHERE IT HAPPENED", SERIF_BOLD, 17, INK);
  const note = "numbered dots mark ten stories in the list below";
  const nw = textWidth(note, SANS, 10);
  drawText(M + CW - nw, y + 14, note, SANS, 10, GREY);
  const mapY = y + 20;
  const mapH = 100;
  drawMap(M, mapY, 480, mapH);
  // DATE CHECK box.
  const bx = M + 492;
  const bw = CW - 492;
  rect(bx, mapY, bw, mapH, CREAM);
  rect(bx, mapY, bw, 2, RED);
  rect(bx, mapY + mapH - 2, bw, 2, RED);
  rect(bx, mapY, 2, mapH, RED);
  rect(bx + bw - 2, mapY, 2, mapH, RED);
  const ix = bx + 12;
  const iy = mapY + 12;
  circle(ix + 8, iy + 8, 9, GREEN);
  thickLine(ix + 3, iy + 8, ix + 7, iy + 12, 2.4, [255, 255, 255]);
  thickLine(ix + 7, iy + 12, ix + 14, iy + 3, 2.4, [255, 255, 255]);
  drawText(ix + 22, iy + 13, "DATE CHECK", SERIF_BOLD, 17, RED);
  const stmt =
    "Every story on this page happened or was first reported on Monday 23 November 2026.";
  drawPara(bx + 12, mapY + 32, stmt, SANS, 11, bw - 24, 1, 13.5, INK, 9.5, "date check statement");
  drawText(bx + 12, mapY + 58, "Left out on purpose:", SANS_BOLD, 10.5, INK);
  const pairs: Array<[string, string]> = [
    [EXCLUDED[0], EXCLUDED[1]],
    [EXCLUDED[2], EXCLUDED[3]],
    [EXCLUDED[4], EXCLUDED[5]],
  ];
  for (let r = 0; r < 3; r++) {
    const left = `${pairs[r][0][0]} (${pairs[r][0][1]})`;
    const right = `${pairs[r][1][0]} (${pairs[r][1][1]})`;
    drawText(bx + 12, mapY + 70 + r * 11, left, SANS, 10, INK);
    drawText(bx + 12 + 236, mapY + 70 + r * 11, right, SANS, 10, INK);
  }
  return mapY + mapH;
}

function drawBriefList(y: number): number {
  drawText(M, y + 14, "IN BRIEF — THE REST OF THE DAY", SERIF_BOLD, 17, INK);
  const colW = (CW - 16) / 2;
  const rowH = 10;
  const listY = y + 20;
  for (let i = 0; i < REST37.length; i++) {
    const col = i < 19 ? 0 : 1;
    const row = col === 0 ? i : i - 19;
    const x = M + col * (colW + 16);
    const by = listY + row * rowH + 8;
    const num = `${i + 1}.`;
    drawText(x, by, num, SANS_BOLD, 9.5, RED);
    const nx = x + textWidth("37. ", SANS_BOLD, 9.5);
    const line = `${REST37[i].headline} (${REST37[i].source})`;
    drawSingleLine(nx, by, line, SANS, 9.5, colW - (nx - x), 8.5, INK, `brief ${i + 1}`);
  }
  return listY + 19 * rowH;
}

function drawPage(): number {
  fillAll(PAPER);
  // Double frame.
  rect(8, 8, W - 16, 3, INK);
  rect(8, H - 11, W - 16, 3, INK);
  rect(8, 8, 3, H - 16, INK);
  rect(W - 11, 8, 3, H - 16, INK);
  rect(13, 13, W - 26, 1, INK);
  rect(13, H - 14, W - 26, 1, INK);
  rect(13, 13, 1, H - 26, INK);
  rect(W - 14, 13, 1, H - 26, INK);

  let y = 22;
  // Masthead.
  drawTextCentred(W / 2, y + 52, "THE WORLD", SERIF_BOLD, 64, INK);
  y += 62;
  rule(M, y, CW, 2.5, RED);
  y += 8;
  drawTextCentred(W / 2, y + 19, "MONDAY 23 NOVEMBER 2026", SERIF_BOLD, 25, RED);
  y += 28;
  y = drawStats(y);
  rule(M, y + 2, CW, 1.6, INK);
  y += 6;
  y = drawTimeline(y);
  y += 6;
  y = drawTopStories(y);
  y += 4;
  y = drawMidStories(y);
  y += 6;
  y = drawMapAndCheck(y);
  y += 6;
  y = drawBriefList(y);
  y += 8;
  const foot =
    "THE WORLD — Monday 23 November 2026 · 50 stories, all first reported today · Sources as credited";
  const fw = textWidth(foot, SANS, 10);
  drawText((W - fw) / 2, y + 10, foot, SANS, 10, GREY);
  y += 12;
  if (y > H - 16) markBad(`page overflows: final y=${y}`);
  return y;
}

function main(): void {
  const endY = drawPage();
  const rgb = downsample();
  const png = encodePng(rgb, W, H);
  const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
  fs.mkdirSync(outDir, { recursive: true });
  const outPath = outDir + "/entry.png";
  fs.writeFileSync(outPath, png);
  const stories = TOP3.length + MID10.length + REST37.length;
  console.log(
    `wrote ${outPath} (${png.length} bytes) fitOk=${fitOk} stories=${stories} endY=${endY}`,
  );
  if (!fitOk) {
    for (const p of fitProblems) console.error("  " + p);
  }
}

main();
